with eligible as (select s.* from stores s where not exists (select 1 from store_sales c where c.store_id = s.id and c.units between 16 and 18)) select region, case when sqft >= 16690 then 'LARGE' else 'SMALL' end as sqft_tier, bit_and(sqft) as sqft_bit_and, sum(sqft) filter (where region = 'North') as north_total_sqft, count(case when city = 'Berlin' then 1 end) as berlin_count from eligible group by region, case when sqft >= 16690 then 'LARGE' else 'SMALL' end
